<script setup>
import {Head,Link} from '@inertiajs/vue3';import {ref} from 'vue';import {rupiah} from '../../lib/money';import CustomerShell from '../../Components/CustomerShell.vue';
const props=defineProps({order:Object,payment:Object});const paymentState=ref(props.payment),errors=ref({}),busy=ref(false),paymentKey=ref(globalThis.crypto?.randomUUID?.()||('payment-'+Date.now()));
async function continuePayment(){errors.value={};busy.value=true;try{const token=document.querySelector('meta[name="csrf-token"]')?.getAttribute('content')||'';const response=await fetch('/payments/orders/'+encodeURIComponent(props.order.order_number),{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify({idempotency_key:paymentKey.value})});const data=await response.json().catch(()=>({}));if(!response.ok){errors.value=data.errors||{payment:[data.message||'Pembayaran tidak dapat dilanjutkan.']};return}paymentState.value=data;const redirect=data?.instructions?.redirect_url||data?.instructions?.payment_url;if(redirect)window.location.assign(redirect)}finally{busy.value=false}}
</script><template><Head title="Status pesanan"/><CustomerShell><main class="lf-container py-7"><Link href="/" class="text-[10px] font-bold text-[#cfff72]">← LFAMILIA STORE</Link><div class="mx-auto mt-3 max-w-2xl"><p class="lf-eyebrow">Status transaksi</p><h1 class="lf-title !text-[24px]">Pesanan {{order.order_number}}</h1><dl class="mt-4 grid gap-2 rounded-lg border border-white/10 bg-[#0d1019]/90 p-3 sm:grid-cols-2"><div v-for="x in [['Produk',order.product_name],['Status',order.status],['Total',rupiah(order.total_idr)],['Dibuat',order.created_at]]" :key="x[0]" class="rounded-md bg-white/[.025] p-2"><dt class="text-[9px] text-white/40">{{x[0]}}</dt><dd class="mt-1 text-[11px] font-bold">{{x[1]}}</dd></div></dl><section v-if="order.status==='PENDING_PAYMENT'" class="mt-3 rounded-lg border border-[#b9ff35]/20 bg-[#b9ff35]/[.06] p-3"><h2 class="text-[13px] font-black">Pembayaran</h2><p v-if="paymentState" class="mt-1 text-[10px]">Status: <strong>{{paymentState.status}}</strong></p><img v-if="paymentState?.instructions?.qr_url" :src="paymentState.instructions.qr_url" class="mt-3 max-h-64 rounded-lg bg-white p-2"><p v-if="paymentState?.instructions?.va_number" class="mt-2 text-[10px]">Nomor VA: <strong>{{paymentState.instructions.va_number}}</strong></p><button class="lf-primary mt-3" :disabled="busy" @click="continuePayment">{{busy?'Memeriksa...':paymentState?'Lanjutkan pembayaran':'Bayar sekarang'}}</button><p v-if="errors.payment" class="mt-2 text-[9px] text-red-300">{{errors.payment[0]}}</p></section><section v-if="order.status==='SUCCESS'&&order.delivery" class="mt-3 rounded-lg border border-emerald-400/25 bg-emerald-400/[.07] p-3 text-[10px]"><h2 class="text-[13px] font-black">Hasil pesanan</h2><p v-if="order.delivery.serial_number">Serial / SN: <strong>{{order.delivery.serial_number}}</strong></p><p v-if="order.delivery.code">Kode / hasil: <strong>{{order.delivery.code}}</strong></p><p v-if="order.delivery.note">{{order.delivery.note}}</p></section></div></main></CustomerShell></template>